"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";

type ExamOption = {
  _id: string;
  title: string;
};

type WrittenSubmissionRow = {
  id: string;
  examId: string;
  userId: string;
  submittedAt: string;
  status: "submitted" | "under-review" | "graded";
  totalScore: number;
  maxScore: number;
  user: { id: string; name: string; email: string } | null;
  exam: { id: string; title: string; totalMarks: number } | null;
};

type Pagination = {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
};

const emptyPagination: Pagination = {
  page: 1,
  limit: 20,
  total: 0,
  totalPages: 0,
};

export function WrittenSubmissionsList() {
  const [submissions, setSubmissions] = useState<WrittenSubmissionRow[]>([]);
  const [exams, setExams] = useState<ExamOption[]>([]);
  const [pagination, setPagination] = useState(emptyPagination);
  const [page, setPage] = useState(1);
  const [examId, setExamId] = useState("all");
  const [status, setStatus] = useState("all");
  const [search, setSearch] = useState("");
  const [pendingOnly, setPendingOnly] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let active = true;

    async function loadExams() {
      try {
        const response = await fetch("/api/admin/written-exams?limit=100");
        const result = (await response.json()) as {
          data?: { exams?: ExamOption[] };
        };

        if (active && response.ok) {
          setExams(result.data?.exams ?? []);
        }
      } catch {
        if (active) {
          setExams([]);
        }
      }
    }

    void loadExams();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    let active = true;
    const controller = new AbortController();
    setLoading(true);
    setError("");
    const params = new URLSearchParams({ page: String(page), limit: "20" });

    if (examId !== "all") {
      params.set("examId", examId);
    }
    if (status !== "all" && !pendingOnly) {
      params.set("status", status);
    }
    if (pendingOnly) {
      params.set("pendingOnly", "true");
    }
    if (search.trim()) {
      params.set("search", search.trim());
    }

    async function loadSubmissions() {
      try {
        const response = await fetch(
          `/api/admin/written-submissions?${params}`,
          { signal: controller.signal },
        );
        const result = (await response.json()) as {
          error?: string;
          data?: {
            submissions?: WrittenSubmissionRow[];
            pagination?: Pagination;
          };
        };

        if (!response.ok) {
          throw new Error(result.error ?? "Unable to load submissions.");
        }

        if (active) {
          setSubmissions(result.data?.submissions ?? []);
          setPagination(result.data?.pagination ?? emptyPagination);
        }
      } catch (caughtError) {
        if (
          !active ||
          (caughtError instanceof DOMException &&
            caughtError.name === "AbortError")
        ) {
          return;
        }

        setError(
          caughtError instanceof Error
            ? caughtError.message
            : "Unable to load submissions.",
        );
      } finally {
        if (active) {
          setLoading(false);
        }
      }
    }

    void loadSubmissions();

    return () => {
      active = false;
      controller.abort();
    };
  }, [examId, page, pendingOnly, search, status]);

  function resetPage() {
    setPage(1);
  }

  function formatDate(value: string) {
    const elapsedSeconds = (Date.now() - new Date(value).getTime()) / 1000;
    const relativeTime = new Intl.RelativeTimeFormat(undefined, {
      numeric: "auto",
    });
    const intervals: [Intl.RelativeTimeFormatUnit, number][] = [
      ["year", 31_536_000],
      ["month", 2_592_000],
      ["day", 86_400],
      ["hour", 3_600],
      ["minute", 60],
    ];

    for (const [unit, seconds] of intervals) {
      if (Math.abs(elapsedSeconds) >= seconds) {
        return relativeTime.format(-Math.round(elapsedSeconds / seconds), unit);
      }
    }

    return relativeTime.format(0, "second");
  }

  return (
    <div className="mt-6">
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <Input
          value={search}
          onChange={(event) => {
            setSearch(event.target.value);
            resetPage();
          }}
          placeholder="Search student name or email"
          aria-label="Search student name or email"
        />
        <Select
          value={examId}
          onChange={(event) => {
            setExamId(event.target.value);
            resetPage();
          }}
          aria-label="Filter by written exam"
        >
          <option value="all">All written exams</option>
          {exams.map((exam) => (
            <option key={exam._id} value={exam._id}>
              {exam.title}
            </option>
          ))}
        </Select>
        <Select
          value={status}
          onChange={(event) => {
            setStatus(event.target.value);
            resetPage();
          }}
          aria-label="Filter by submission status"
        >
          <option value="all">All statuses</option>
          <option value="submitted">Submitted</option>
          <option value="under-review">Under review</option>
          <option value="graded">Graded</option>
        </Select>
        <label className="flex min-h-11 cursor-pointer items-center gap-2 rounded-md border border-border bg-card px-3 text-sm text-primary">
          <input
            type="checkbox"
            checked={pendingOnly}
            onChange={(event) => {
              setPendingOnly(event.target.checked);
              resetPage();
            }}
            className="h-4 w-4 cursor-pointer accent-primary"
          />
          Pending review
        </label>
      </div>

      {error ? (
        <p
          role="alert"
          className="mt-4 rounded-md bg-red-50 p-3 text-sm text-red-700"
        >
          {error}
        </p>
      ) : null}

      <div className="mt-5 overflow-hidden rounded-lg border border-border bg-card">
        {loading ? (
          <p className="p-8 text-sm text-muted">Loading submissions...</p>
        ) : submissions.length === 0 ? (
          <p className="p-10 text-center text-sm text-muted">
            No written submissions found.
          </p>
        ) : (
          <>
            <div className="hidden overflow-x-auto md:block">
              <table className="w-full min-w-[760px] text-left text-sm">
                <thead className="border-b border-border text-xs uppercase tracking-wide text-muted">
                  <tr>
                    <th className="px-5 py-3 font-medium">Student</th>
                    <th className="px-5 py-3 font-medium">Exam</th>
                    <th className="px-5 py-3 font-medium">Submitted</th>
                    <th className="px-5 py-3 font-medium">Status</th>
                    <th className="px-5 py-3 font-medium">Score</th>
                    <th className="px-5 py-3 text-right font-medium">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {submissions.map((submission) => (
                    <tr key={submission.id}>
                      <td className="px-5 py-3">
                        <span className="block font-medium text-primary">
                          {submission.user?.name ?? "Unknown student"}
                        </span>
                        <span className="block text-xs text-muted">
                          {submission.user?.email ?? ""}
                        </span>
                      </td>
                      <td className="px-5 py-3 text-foreground">
                        {submission.exam?.title ?? "Unknown exam"}
                      </td>
                      <td className="px-5 py-3 text-muted">
                        {formatDate(submission.submittedAt)}
                      </td>
                      <td className="px-5 py-3">
                        <Badge className="text-muted">
                          {submission.status}
                        </Badge>
                      </td>
                      <td className="px-5 py-3 text-muted">
                        {submission.status === "graded"
                          ? `${submission.totalScore} / ${submission.maxScore}`
                          : "—"}
                      </td>
                      <td className="px-5 py-3 text-right">
                        <Link
                          href={`/admin/written-submissions/${submission.id}`}
                          className="cursor-pointer text-sm font-medium text-accent hover:underline"
                        >
                          Review
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="divide-y divide-border md:hidden">
              {submissions.map((submission) => (
                <article key={submission.id} className="p-4">
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <p className="truncate text-sm font-medium text-primary">
                        {submission.user?.name ?? "Unknown student"}
                      </p>
                      <p className="truncate text-xs text-muted">
                        {submission.user?.email ?? ""}
                      </p>
                    </div>
                    <Badge className="shrink-0 text-muted">
                      {submission.status}
                    </Badge>
                  </div>
                  <p className="mt-3 text-sm text-foreground">
                    {submission.exam?.title ?? "Unknown exam"}
                  </p>
                  <div className="mt-2 flex items-center justify-between text-xs text-muted">
                    <span>{formatDate(submission.submittedAt)}</span>
                    <span>
                      {submission.status === "graded"
                        ? `${submission.totalScore} / ${submission.maxScore}`
                        : "—"}
                    </span>
                  </div>
                  <Link
                    href={`/admin/written-submissions/${submission.id}`}
                    className="mt-3 inline-flex min-h-9 cursor-pointer items-center text-sm font-medium text-accent"
                  >
                    Review
                  </Link>
                </article>
              ))}
            </div>
          </>
        )}
      </div>

      {pagination.totalPages > 1 ? (
        <div className="mt-4 flex items-center justify-between text-sm">
          <span className="text-muted">
            Page {pagination.page} of {pagination.totalPages}
          </span>
          <div className="flex gap-2">
            <button
              type="button"
              disabled={page <= 1}
              onClick={() => setPage((current) => Math.max(1, current - 1))}
              className="cursor-pointer rounded border border-border px-3 py-2 text-primary disabled:cursor-not-allowed disabled:opacity-40"
            >
              Previous
            </button>
            <button
              type="button"
              disabled={page >= pagination.totalPages}
              onClick={() => setPage((current) => current + 1)}
              className="cursor-pointer rounded border border-border px-3 py-2 text-primary disabled:cursor-not-allowed disabled:opacity-40"
            >
              Next
            </button>
          </div>
        </div>
      ) : null}
    </div>
  );
}
